import math

def dot_product(v1, v2):
    return sum(a * b for a, b in zip(v1, v2))

def magnitude(v):
    return math.sqrt(sum(a * a for a in v))

def cosine_similarity(v1, v2):
    # divides dot product by magnitudes
    return dot_product(v1, v2) / (magnitude(v1) * magnitude(v2))

short_chunk_embedding = [0.5, 0.3, 0.2]
long_chunk_embedding = [1.5, 0.9, 0.6]  # same direction, much larger magnitude
unrelated_embedding = [-0.2, 0.1, -0.9]

print("Comparing a short chunk against a long chunk on the same topic:")
print(f"  cosine similarity: {cosine_similarity(short_chunk_embedding, long_chunk_embedding):.3f}")
print(f"  magnitudes: short={magnitude(short_chunk_embedding):.3f}, long={magnitude(long_chunk_embedding):.3f}\n")

print("Comparing the short chunk against an unrelated chunk:")
print(f"  cosine similarity: {cosine_similarity(short_chunk_embedding, unrelated_embedding):.3f}")

print("\nNotice the same direction scores near 1.0 regardless of magnitude.")
